const loader = document.getElementById('loader');

window.addEventListener('load', () => {
  setTimeout(() => {
    if (loader) {
      loader.style.opacity = '0';
      loader.style.pointerEvents = 'none';
    }
  }, 300);
});

document.body.style.overflow = 'hidden';


(async function () {
  const stage = document.getElementById('stage');

  /* ---------- images (embedded) ---------- */
  const IMG_ENV  = "data:image/jpeg;base64,";    // your envelope picture, with the seal + hint text removed
  const IMG_SEAL = "data:image/png;base64,";   // the wax seal, cut out of your picture
  const IMG_GLOW = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=";   // the R&Z letters only, blurred, on pure black (added as light)

  /* ---------- geometry: everything is measured in picture pixels ---------- */
  const IW = 519, IH = 892;                 // picture size
  const W = 1, H = IH / IW, S = W / IW;     // world units: picture width = 1
  const sx = x => x * S, sy = y => (IH - y) * S;

  // the four parts, cut exactly along the folds of the picture
  const TOP    = [[18.5, 0], [519, 0], [519, 30.2], [276.6, 496.7]];
  const BOTTOM = [[276.8, 423.2], [519, 842.5], [519, 892], [5.2, 892]];
  const LEFT   = [[0, 0], [18.5, 0], [256.6, 458.1], [5.2, 892], [0, 892]];
  const RIGHT  = [[519, 30.2], [296.8, 457.8], [519, 842.5]];
  const SEAL_BOX = { x: 177, y: 347, w: 192, h: 215 };   // seal position in the picture

  /* ---------- renderer / camera ---------- */
  let renderer;
  try { renderer = new THREE.WebGLRenderer({ antialias: true }); }
  catch (e) { stage.innerHTML = '<p class="fallback">WebGL is not available on this device.</p>'; return; }
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  stage.appendChild(renderer.domElement);

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0xf8efdf);

  const D = 3.4;                                           // farther camera = calmer perspective
  const fov = 2 * Math.atan((H / 2) / D) * 180 / Math.PI;  // the picture exactly fills the view
  const camera = new THREE.PerspectiveCamera(fov, W / H, 0.1, 30);
  camera.position.set(0, 0, D);

  const resize = () => renderer.setSize(stage.clientWidth, stage.clientHeight, false);
  new ResizeObserver(resize).observe(stage);
  resize();

  /* ---------- load textures ---------- */
  const loadTex = url => new Promise((res, rej) => new THREE.TextureLoader().load(url, res, undefined, rej));
  const [envTex, sealTex, glowTex] = await Promise.all([loadTex(IMG_ENV), loadTex(IMG_SEAL), loadTex(IMG_GLOW)]);
  envTex.anisotropy = renderer.capabilities.getMaxAnisotropy();
  envTex.repeat.set(1 / W, 1 / H);     // ShapeGeometry UVs are raw x/y -> map them onto the full picture

  try {
    await Promise.race([
      Promise.all([document.fonts.load('100px "Great Vibes"'), document.fonts.load('40px "Cormorant Garamond"')]),
      new Promise(r => setTimeout(r, 1800))
    ]);
  } catch (e) {}

  /* ---------- helpers ---------- */
  function shapeOf(pts) {
    const sh = new THREE.Shape();
    pts.forEach(([x, y], i) => i ? sh.lineTo(sx(x), sy(y)) : sh.moveTo(sx(x), sy(y)));
    sh.closePath();
    return sh;
  }
  const paper = () => new THREE.MeshBasicMaterial({ map: envTex, transparent: true, side: THREE.DoubleSide });
  const piece = (pts, order) => {
    const m = new THREE.Mesh(new THREE.ShapeGeometry(shapeOf(pts)), paper());
    m.renderOrder = order;
    return m;
  };

  /* ---------- envelope: lining + 4 separate parts ---------- */
  // lining = what you see under the flaps once they open
  const liningC = document.createElement('canvas'); liningC.width = 8; liningC.height = 256;
  { const g = liningC.getContext('2d'); const gr = g.createLinearGradient(0, 0, 0, 256);
    gr.addColorStop(0, 'rgb(228,217,203)'); gr.addColorStop(1, 'rgb(219,206,191)');
    g.fillStyle = gr; g.fillRect(0, 0, 8, 256); }
  const lining = new THREE.Mesh(new THREE.PlaneGeometry(W, H),
    new THREE.MeshBasicMaterial({ map: new THREE.CanvasTexture(liningC), transparent: true }));
  lining.position.z = -0.002; lining.renderOrder = 0;
  scene.add(lining);

  const left = piece(LEFT, 1);   left.position.set(-W / 2, -H / 2, 0.001);   scene.add(left);
  const right = piece(RIGHT, 1); right.position.set(-W / 2, -H / 2, 0.001);  scene.add(right);

  // bottom flap: hinged on the bottom edge
  const bottomPivot = new THREE.Group();
  bottomPivot.position.set(0, -H / 2, 0.002);
  const bottom = piece(BOTTOM, 2);
  bottom.position.set(-W / 2, 0, 0);
  bottomPivot.add(bottom);
  scene.add(bottomPivot);

  // top flap: hinged on the top edge (carries the seal)
  const topPivot = new THREE.Group();
  topPivot.position.set(0, H / 2, 0.004);
  const top = piece(TOP, 3);
  top.position.set(-W / 2, -H, 0);
  topPivot.add(top);
  scene.add(topPivot);

  /* ---------- seal (rides on the top flap) + soft lights ---------- */
  const sealW = SEAL_BOX.w * S, sealH = SEAL_BOX.h * S;
  const scx = SEAL_BOX.x + SEAL_BOX.w / 2, scy = SEAL_BOX.y + SEAL_BOX.h / 2;
  const sealGroup = new THREE.Group();
  sealGroup.position.set((scx / IW - .5) * W, -(scy / IH) * H, 0.006);
  topPivot.add(sealGroup);

  const sealMesh = new THREE.Mesh(new THREE.PlaneGeometry(sealW, sealH),
    new THREE.MeshBasicMaterial({ map: sealTex, transparent: true, depthWrite: false }));
  sealMesh.renderOrder = 4;
  sealGroup.add(sealMesh);

  const letterGlowMat = new THREE.MeshBasicMaterial({
    map: glowTex, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false
  });
  const letterGlow = new THREE.Mesh(new THREE.PlaneGeometry(sealW, sealH), letterGlowMat);
  letterGlow.position.z = 0.001; letterGlow.renderOrder = 5;
  sealGroup.add(letterGlow);

  const haloC = document.createElement('canvas'); haloC.width = haloC.height = 128;
  { const g = haloC.getContext('2d');
    g.fillStyle = '#000'; g.fillRect(0, 0, 128, 128);
    const gr = g.createRadialGradient(64, 64, 0, 64, 64, 62);
    gr.addColorStop(0, 'rgba(255,200,110,1)'); gr.addColorStop(.4, 'rgba(255,150,50,.5)'); gr.addColorStop(1, 'rgba(0,0,0,0)');
    g.fillStyle = gr; g.fillRect(0, 0, 128, 128); }
  const halo = new THREE.Sprite(new THREE.SpriteMaterial({
    map: new THREE.CanvasTexture(haloC), transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, depthTest: false
  }));
  halo.position.z = 0.002; halo.renderOrder = 6;
  sealGroup.add(halo);

  /* ---------- timeline ---------- */
  const clamp01 = x => Math.min(1, Math.max(0, x));
  const seg = (t, a, b) => clamp01((t - a) / (b - a));
  const ease = t => t < .5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;

  const SLOW = 2.6;         // 1 = fast, higher = slower
  const LETTER_GLOW = 0.9;  // soft glow on the seal letters (0 = none)
  const HALO_GLOW = 0.55;   // soft light around the circle (0 = none)

  function update(t, now) {
    const idle = t < 0;
    const tt = Math.max(t, 0);

    // sides + lining vanish FIRST, the two flaps (with the seal) vanish after them
    const opBody  = 1 - ease(seg(tt, 1.0, 2.0));
    const opFlaps = 1 - ease(seg(tt, 1.9, 3.0));

    // 1) soft light on the letters and around the circle
    let glow = ease(seg(tt, 0, .9)) * (1 - seg(tt, 1.5, 2.4));
    if (idle) glow = .12 + .07 * Math.sin(now / 1100);
    letterGlowMat.opacity = glow * LETTER_GLOW * opFlaps;
    halo.material.opacity = glow * HALO_GLOW * opFlaps;
    halo.scale.setScalar(sealW * 1.9 + glow * .12);

    // 2) top flap opens first, the bottom flap follows right behind it - both slowly
    const pt = ease(seg(tt, .2, 3.2));
    const pb = ease(seg(tt, .4, 3.4));
    topPivot.rotation.x = -Math.PI * pt;
    bottomPivot.rotation.x = Math.PI * pb;
    top.material.color.setScalar(1 - .2 * Math.sin(pt * Math.PI));
    bottom.material.color.setScalar(1 - .2 * Math.sin(pb * Math.PI));

    // 3) fades
    [left, right, lining].forEach(m => m.material.opacity = opBody);
    left.visible = right.visible = lining.visible = opBody > .001;
    [top, bottom, sealMesh].forEach(m => m.material.opacity = opFlaps);
    topPivot.visible = bottomPivot.visible = opFlaps > .001;

  }

  let start = null;
  function frame(now) {
    update(start === null ? -1 : (now - start) / 1000 / SLOW, now);
    renderer.render(scene, camera);
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);

  const overlay = document.getElementById('envelope');
  const site = document.getElementById('site');
  const replay = document.getElementById('replay');
  let openTimer = null;

  function showSite() {
    if (openTimer) clearTimeout(openTimer);
    site.setAttribute('aria-hidden', 'false');
    document.body.style.overflow = 'auto';
    overlay.classList.add('is-hidden');
    replay.classList.add('visible');
    window.scrollTo({ top: 0, behavior: 'instant' });
  }

  function open() {
    if (start !== null) return;
    start = performance.now();
    stage.classList.add('open');
    openTimer = setTimeout(showSite, 7700);
  }

  stage.addEventListener('click', open);
  stage.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); open(); } });

  replay.addEventListener('click', () => {
    if (openTimer) clearTimeout(openTimer);
    start = null;
    stage.classList.remove('open');
    overlay.classList.remove('is-hidden');
    site.setAttribute('aria-hidden', 'true');
    document.body.style.overflow = 'hidden';
    window.scrollTo({ top: 0, behavior: 'instant' });
  });
})();



// Replace this date with the couple's real wedding date.
const weddingDate=new Date('2026-12-03T19:30:00+04:00');  // 3 Dec 2026, 7:30 PM (New York time)
function tick(){
 const now=new Date(), diff=Math.max(0,weddingDate-now);
 const d=Math.floor(diff/86400000),h=Math.floor(diff/3600000)%24,m=Math.floor(diff/60000)%60,s=Math.floor(diff/1000)%60;
 document.getElementById('days').textContent=String(d).padStart(3,'0');
 document.getElementById('hours').textContent=String(h).padStart(2,'0');
 document.getElementById('minutes').textContent=String(m).padStart(2,'0');
 document.getElementById('seconds').textContent=String(s).padStart(2,'0');
}
tick();setInterval(tick,1000);

document.getElementById('rsvpButton').addEventListener('click',()=>document.getElementById('rsvpDialog').showModal());

// The flower rides the centre line of the schedule while the page is scrolled.
(function(){
  const tl=document.querySelector('.timeline'), fl=document.querySelector('.timeline-flower');
  if(!tl||!fl) return;
  let ticking=false;
  function place(){
    ticking=false;
    const r=tl.getBoundingClientRect();
    const y=Math.max(0,Math.min(r.height,innerHeight*0.45-r.top));   // follows the middle of the screen
    fl.style.transform='translate(-50%,'+(y-fl.offsetHeight/2)+'px) rotate('+(y*0.3)+'deg)';
  }
  function onScroll(){ if(!ticking){ ticking=true; requestAnimationFrame(place); } }
  addEventListener('scroll',onScroll,{passive:true});
  addEventListener('resize',onScroll);
  place();
})();
